#!/usr/bin/env bash\n\n# Xiaomi HyperOS Mini Debloater - Installation Verifier\n# Checks all prerequisites before running the main script\n\nset -Eeuo pipefail\n\necho \"==========================================\"\necho \"Xiaomi HyperOS Mini Debloater - Setup\"\necho \"==========================================\"\necho\n\ncheck_bash() {\n  if [[ ${BASH_VERSINFO[0]} -lt 4 ]]; then\n    echo \"❌ Fehler: Bash 4.0+ erforderlich (aktuell: ${BASH_VERSINFO[0]}.${BASH_VERSINFO[1]})\"\n    exit 1\n  fi\n  echo \"✓ Bash ${BASH_VERSINFO[0]}.${BASH_VERSINFO[1]} OK\"\n}\n\ncheck_adb() {\n  if command -v adb >/dev/null 2>&1; then\n    local version\n    version=$(adb version 2>&1 | head -n 1)\n    echo \"✓ ADB installiert\"\n    return 0\n  fi\n\n  echo \"❌ ADB nicht gefunden\"\n  echo\n  echo \"Installiere Android Platform Tools:\"\n  echo\n  if [[ \"$OSTYPE\" == \"linux-gnu\"* ]]; then\n    echo \"  Ubuntu/Debian: sudo apt-get install android-tools-adb\"\n    echo \"  Fedora: sudo dnf install android-tools\"\n    echo \"  Arch: sudo pacman -S android-tools\"\n  elif [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n    echo \"  macOS: brew install android-platform-tools\"\n  elif [[ \"$OSTYPE\" == \"msys\" ]] || [[ \"$OSTYPE\" == \"cygwin\" ]]; then\n    echo \"  Windows: https://developer.android.com/studio/releases/platform-tools\"\n  fi\n  echo\n  return 1\n}\n\ncheck_device() {\n  if adb devices 2>&1 | grep -q \"device$\"; then\n    echo \"✓ ADB-Gerät verbunden und autorisiert\"\n    return 0\n  fi\n\n  echo \"⚠ Kein Gerät verbunden oder nicht autorisiert\"\n  echo\n  echo \"Schritte:\"\n  echo \"  1. Verbinde Xiaomi-Gerät über USB\"\n  echo \"  2. Aktiviere USB-Debugging (Einstellungen → Entwickler-Optionen)\"\n  echo \"  3. Akzeptiere die Autorisierungsaufforderung auf dem Gerät\"\n  echo \"  4. Führe aus: adb devices\"\n  echo\n  return 1\n}\n\nmain() {\n  echo \"Überprüfe Voraussetzungen...\"\n  echo\n\n  check_bash\n  echo\n\n  if ! check_adb; then\n    echo \"Bitte installiere Android Platform Tools und versuche erneut.\"\n    exit 1\n  fi\n  echo\n\n  if ! check_device; then\n    echo \"Bitte verbinde dein Gerät und aktiviere USB-Debugging.\"\n    exit 1\n  fi\n  echo\n\n  echo \"==========================================\"\n  echo \"✓ Alles bereit!\"\n  echo \"==========================================\"\n  echo\n  echo \"Starte das Debloater-Skript:\"\n  echo\n  echo \"  bash \\\"Xiaomi HyperOS mini debloade\\\"\"\n  echo\n  echo \"Oder im Dry-Run-Modus (nur Vorschau):\"\n  echo\n  echo \"  DRY_RUN=true bash \\\"Xiaomi HyperOS mini debloade\\\"\"\n  echo\n}\n\nmain \"$@\"\n"
